package com.ewaste.controller;
import com.ewaste.dto.CreatePickupRequest;import com.ewaste.model.*;import com.ewaste.repository.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/pickups") public class PickupController {
 private final PickupRepository pickups;private final WasteReportRepository reports;private final UserRepository users;
 public PickupController(PickupRepository p,WasteReportRepository r,UserRepository u){pickups=p;reports=r;users=u;}
 @PostMapping @Transactional public ResponseEntity<?> create(@Valid @RequestBody CreatePickupRequest r,Authentication a){AppUser user=users.findByEmailIgnoreCase(a.getName()).orElseThrow();WasteReport report=reports.findById(r.reportId()).orElse(null);if(report==null)return ResponseEntity.badRequest().body(Map.of("message","Report not found"));if(user.getRole()!=Role.ADMIN&&!report.getUser().getId().equals(user.getId()))return ResponseEntity.status(403).body(Map.of("message","You can only schedule your own report"));if(pickups.existsByReportId(report.getId()))return ResponseEntity.status(409).body(Map.of("message","A pickup already exists for this report"));if(r.scheduledAt().isBefore(java.time.LocalDateTime.now()))return ResponseEntity.badRequest().body(Map.of("message","Schedule time must be in the future"));PickupRequest p=new PickupRequest();p.setReport(report);p.setRequester(report.getUser());p.setScheduledAt(r.scheduledAt());p.setStatus(WasteStatus.SCHEDULED);return ResponseEntity.status(201).body(pickups.save(p));}
 @GetMapping public List<PickupRequest> list(Authentication a){AppUser u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();return switch(u.getRole()){case ADMIN->pickups.findAll();case COLLECTOR->pickups.findByCollectorIdOrderByScheduledAtDesc(u.getId());case USER->pickups.findByRequesterIdOrderByScheduledAtDesc(u.getId());};}
 @GetMapping("/all") @PreAuthorize("hasRole('ADMIN')") public List<PickupRequest> all(){return pickups.findAll();}
 @PutMapping("/{id}/assign/{collectorId}") @PreAuthorize("hasRole('ADMIN')") @Transactional public ResponseEntity<?> assign(@PathVariable Long id,@PathVariable Long collectorId){PickupRequest p=pickups.findById(id).orElse(null);AppUser c=users.findById(collectorId).orElse(null);if(p==null||c==null)return ResponseEntity.notFound().build();if(c.getRole()!=Role.COLLECTOR)return ResponseEntity.badRequest().body(Map.of("message","Selected account is not a collector"));p.setCollector(c);p.setStatus(WasteStatus.ASSIGNED);return ResponseEntity.ok(pickups.save(p));}
 @PatchMapping("/{id}/status") @Transactional public ResponseEntity<?> status(@PathVariable Long id,@RequestBody Map<String,String> body,Authentication a){PickupRequest p=pickups.findById(id).orElse(null);if(p==null)return ResponseEntity.notFound().build();AppUser actor=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(actor.getRole()==Role.USER&&!p.getRequester().getId().equals(actor.getId()))return ResponseEntity.status(403).body(Map.of("message","Forbidden"));if(actor.getRole()==Role.COLLECTOR&&(p.getCollector()==null||!p.getCollector().getId().equals(actor.getId())))return ResponseEntity.status(403).body(Map.of("message","This pickup is not assigned to you"));WasteStatus next;try{next=WasteStatus.valueOf(body.getOrDefault("status","").toUpperCase());}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid status"));}if(actor.getRole()==Role.USER&&next!=WasteStatus.CANCELLED)return ResponseEntity.status(403).body(Map.of("message","Users can only cancel a pickup"));if(actor.getRole()==Role.COLLECTOR&&!List.of(WasteStatus.ACCEPTED,WasteStatus.PICKED_UP,WasteStatus.COMPLETED).contains(next))return ResponseEntity.badRequest().body(Map.of("message","Invalid collector status"));if(actor.getRole()==Role.ADMIN&&next==WasteStatus.SCHEDULED){}p.setStatus(next);if(next==WasteStatus.COMPLETED&&!p.isRewardGranted()){AppUser requester=p.getRequester();requester.setPoints(requester.getPoints()+10);users.save(requester);p.setRewardGranted(true);}return ResponseEntity.ok(pickups.save(p));}
}
